public class TFMPageAttributeAttribute extends SysAttribute implements SysExtensionIAttribute
{
    str				name;
    str				xPath;
    anytype			defaultValue;
}

Method.Source:
void new(str _name = '', str _xPath = '', anytype _defaultValue = null)
{
    super();
    defaultValue = _defaultValue;
    name = _name;    
    xPath=_xPath;    
}

public str parmXPath(str _xPath = xPath)
{
    xPath = _xPath;

    return xPath;
}

public str parmName(str _name = name)
{
    name = _name;

    return name;
}
